describe('Product List Display', () => {
    beforeEach(() => {
        cy.visit('https://www.saucedemo.com');
        cy.get('input[name="user-name"]').type('standard_user');
        cy.get('input[name="password"]').type('secret_sauce');
        cy.get('input[type="submit"]').click();
    });

    it('should display exactly 6 product cards on the inventory page', () => {
        cy.get('.inventory_item').should('have.length', 6);
    });

    it('should ensure each product card has a non-empty name and a price starting with $', () => {
        cy.get('.inventory_item').each(($el) => {
            cy.wrap($el).find('.inventory_item_name').invoke('text').should('not.be.empty');
            cy.wrap($el).find('.inventory_item_price').invoke('text').should('match', /^\$/);
        });
    });
});
